// engine/schema/common.ts keeps its own ID_RE (the schema package does not import engine/lib).
// Ids generated by engine/lib/ids.ts must match ID_RE. newId() keeps process-global monotonic state, and this
// test feeds it far-future times, so it runs in a child process to avoid polluting other tests' clock.
import { expect, test } from 'bun:test';
import path from 'node:path';
import { ID_RE } from '../../../engine/schema/index.ts';
import { repoRoot } from '../../helpers.ts';

const idsPath = path.join(repoRoot, 'engine', 'lib', 'ids.ts');

test('ID_RE matches engine/lib/ids.ts newId() output', () => {
  const script = `
    import { newId } from ${JSON.stringify(idsPath)};
    const out = [];
    for (const prefix of ['task', 'run', 'apr', 'wfi', 'grant', 'a1'])
      for (const now of [0, Date.UTC(2026, 9, 18), 2 ** 48 - 1]) out.push(newId(prefix, now));
    console.log(JSON.stringify(out));`;
  const r = Bun.spawnSync([process.execPath, '-e', script], { cwd: repoRoot });
  expect(r.exitCode).toBe(0);
  const ids = JSON.parse(r.stdout.toString()) as string[];
  expect(ids.length).toBe(18);
  for (const id of ids) expect(ID_RE.test(id)).toBe(true);
});
